                JsonSerializer.Serialize(writer, episode.MemorableMoments, jsonSerializerOptions);
            }
            if (episode.UsViewersMillionsOption.IsSet)
                if (episode.UsViewersMillionsOption.Value != null)
                    writer.WriteNumber("us_viewers_millions", episode.UsViewersMillionsOption.Value!.Value);
                else
                    writer.WriteNull("us_viewers_millions");

            if (episode.ViewerRatingOption.IsSet)
                if (episode.ViewerRatingOption.Value != null)
                    writer.WriteNumber("viewer_rating", episode.ViewerRatingOption.Value!.Value);
                else
                    writer.WriteNull("viewer_rating");
        }
    }
}
